#include <vector>
#include <iostream>

std::vector<int> scores{80, 90, 95};
for (int x : scores) {
    std::cout << x << ' ';
}

std::vector<int> scores{80, 90};
scores.push_back(95);
scores[1] = 92;
std::cout << scores.size() << '\n';
std::cout << scores.front() << ' ';
std::cout << scores.back() << '\n';
for (int x : scores) std::cout << x << ' ';

std::vector<int> a(3, 7);
std::vector<int> b{3, 7};
std::vector<int> c(3);
for (int x : a) std::cout << x << ' ';
std::cout << '\n';
for (int x : b) std::cout << x << ' ';
std::cout << '\n';
for (int x : c) std::cout << x << ' ';

std::vector<int> v{10, 20, 30};
v.insert(v.begin() + 1, 15);
v.erase(v.begin() + 2);
for (int x : v) std::cout << x << ' ';

std::vector<int> v{10, 20, 30};
for (int x : v) x += 1;
for (int x : v) std::cout << x << ' ';
std::cout << '\n';
for (int& x : v) x += 1;
for (int x : v) std::cout << x << ' ';

std::deque<int> q{101, 102};
q.push_back(103);
q.push_front(99);
std::cout << q.front() << '\n';
q.pop_front();
for (int x : q) std::cout << x << ' ';
std::cout << '\n' << q[1];

std::list<int> a{10, 30};
auto it = a.begin();
std::cout << *it << ' ';
++it;
std::cout << *it;

std::list<std::string> songs{"A", "C"};
auto pos = std::next(songs.begin());
songs.insert(pos, "B");
songs.erase(pos);
for (const auto& s : songs) std::cout << s << ' ';

std::list<int> a{3, 1, 1, 2, 1};
a.sort();
a.unique();
a.remove(2);
for (int x : a) std::cout << x << ' ';

std::forward_list<int> tasks{20, 30};
tasks.push_front(10);
auto pos = tasks.begin();
tasks.erase_after(pos);
tasks.insert_after(pos, 15);
for (int x : tasks) std::cout << x << ' ';

std::forward_list<int> a{10, 20};
a.insert_after(a.before_begin(), 5);
a.erase_after(a.before_begin());
for (int x : a) std::cout << x << ' ';

std::string s = "nju";
s += " beamer";
s[0] = 'N';
std::cout << s << '\n';
std::cout << s.substr(0, 3) << '\n';
std::cout << s.find("beamer");

std::string line;
std::getline(std::cin, line);
std::cout << line << '\n' << line.size();

std::string s = "good morning";
auto pos = s.find("bye");
if (pos == std::string::npos) {
    std::cout << "not found";
} else {
    std::cout << s.substr(pos);
}

std::vector<int> v(3, 10);
v.push_back(20);
v.erase(v.begin() + 1);
for (int x : v) std::cout << x << ' ';
std::cout << '\n' << v.size();
